    "contents": "-- Make the host server identity explicit for every newly stored pane.\nCREATE TABLE `panes_new` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`tmux_pane_id` text NOT NULL,\n\t`tmux_server_id` text NOT NULL,\n\t`agent_session_id` text,\n\t`agent_execution_id` text,\n\t`session_name` text NOT NULL,\n\t`window_id` text NOT NULL,\n\t`kind` text NOT NULL,\n\t`name` text NOT NULL,\n\t`cwd` text NOT NULL,\n\t`workspace_id` text,\n\t`agent_id` text,\n\t`state` text NOT NULL,\n\t`title` text,\n\t`last_seen_at` text NOT NULL,\n\t`created_at` text NOT NULL,\n\t`updated_at` text NOT NULL\n);\n--> statement-breakpoint\nINSERT INTO `panes_new` (\n\t`id`,\n\t`tmux_pane_id`,\n\t`tmux_server_id`,\n\t`agent_session_id`,\n\t`agent_execution_id`,\n\t`session_name`,\n\t`window_id`,\n\t`kind`,\n\t`name`,\n\t`cwd`,\n\t`workspace_id`,\n\t`agent_id`,\n\t`state`,\n\t`title`,\n\t`last_seen_at`,\n\t`created_at`,\n\t`updated_at`\n)\nSELECT\n\t`id`,\n\t`tmux_pane_id`,\n\t`tmux_server_id`,\n\t`agent_session_id`,\n\t`agent_execution_id`,\n\t`session_name`,\n\t`window_id`,\n\t`kind`,\n\t`name`,\n\t`cwd`,\n\t`workspace_id`,\n\t`agent_id`,\n\t`state`,\n\t`title`,\n\t`last_seen_at`,\n\t`created_at`,\n\t`updated_at`\nFROM `panes`\n-- The pre-identity sentinel cannot identify a live tmux server and is not recoverable.\nWHERE `tmux_server_id` <> 'legacy';\n--> statement-breakpoint\nDROP TABLE `panes`;\n--> statement-breakpoint\nALTER TABLE `panes_new` RENAME TO `panes`;\n--> statement-breakpoint\nCREATE UNIQUE INDEX `panes_tmux_server_pane_id_index` ON `panes` (`tmux_server_id`,`tmux_pane_id`);\n--> statement-breakpoint\nCREATE INDEX `panes_agent_session_index` ON `panes` (`agent_session_id`);\n"
